{"command": "mkdir -p /tmp/ht && cd /tmp/ht && cat <<'EOF' > main.rs
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
fn h<T: Hash>(x: &T) -> u64 { let mut s = DefaultHasher::new(); x.hash(&mut s); s.finish() }
fn main(){
  for n in ["w","l","p","o","i","c","y","n","q","f","s","z","d","m","a","x","k","r","t","g","u","v","h","e","j","b"] {
     let v = h(&n.to_string());
     let f = v as f64 / u64::MAX as f64;
     println!("{} {:016x} {:.6}  (h%1000={})", n, v, f, v%1000);
  }
}
EOF
rustc -O main.rs -o ht 2>&1 | head -20 && ./ht"}

