                self.grid[self.y][self.x+k]=(ch if k==0 else '', self.style)
        self.x+=w
        if self.x>=self.cols and self.autowrap:
            self.x=0; self.y+=1
    def resize(self,cols,rows):
        self.cols=cols; self.rows=rows
        for r in self.grid:
            while len(r)<cols: r.append((' ',None))
        del self.grid[rows:]
        self.x=min(self.x,cols-1); self.y=min(self.y,rows-1)
    def feed(self,data):
        if isinstance(data,bytes): data=data.decode('utf-8',errors='replace')
        i=0; n=len(data)
        while i<n:
            c=data[i]
            if c=='\x1b':
                m=re.match(r'\x1b\[([0-9;?]*)([A-Za-z@])',data[i:])
