                i+=1; continue
            if c=='\r': self.x=0; i+=1; continue
            if c=='\n': self.y+=1
            elif c=='\b': self.x=max(0,self.x-1)
            elif c=='\t': self.x=min(self.cols-1,(self.x//8+1)*8)
            else:
                w=self.charwidth(c)
                self.put(c,w)
            i+=1
    def charwidth(self,c):
        o=ord(c)
        if o==0: return 1
        return 1
