{"command": "cd /tmp/ht && cat <<'EOF' > main.rs
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
fn hs(s: &str) -> u64 { let mut h = DefaultHasher::new(); s.hash(&mut h); h.finish() }
fn main(){
  // args: targets like 0.005,0.015,...  find a name whose hash fraction is within 0.001
  let targets: Vec<f64> = std::env::args().skip(1).map(|s| s.parse().unwrap()).collect();
  let mut found: Vec<Option<(f64,String)>> = vec![None; targets.len()];
  for i in 0..6_000_000u64 {
     let s = format!("m{}", i);
     let v = hs(&s);
     let f = v as f64 / u64::MAX as f64;
     for (k,t) in targets.iter().enumerate() {
        if found[k].is_none() && (f - t).abs() < 0.0012 {
           found[k] = Some((f, s.clone()));
        }
     }
     if found.iter().all(|x| x.is_some()) { break }
  }
  for (t,f) in targets.iter().zip(found.iter()) {
     match f { Some((ff,s)) => println!("{}\t{}\t{:.9}", t, s, ff), None => println!("{}\tMISSING\t0", t) }
  }
}
