import os,pty,time,fcntl,termios,struct,select,sys
sys.path.insert(0,'/tmp/h')
from term import Term
def run(args, data, label, ctty=True, wait=1.2, cols=120, rows=40):
    master,slave=pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',rows,cols,0,0))
    r,w=os.pipe()
    pid=os.fork()
    if pid==0:
        os.setsid()
        if ctty:
            fd=os.open(slave, os.O_RDWR)   # sets ctty
            os.dup2(fd,0); os.dup2(fd,1); os.dup2(fd,2)
        else:
            os.dup2(r,0); os.dup2(slave,1); os.dup2(slave,2)
        os.close(master); os.close(slave); os.close(r); os.close(w)
        os.chdir('/workspace')
        try: os.execv('/workspace/executable',['/workspace/executable']+args)
        except Exception: os._exit(127)
    os.close(slave)
    if data:
        for d in data: os.write(w,d); time.sleep(0.05)
    os.close(w)
    buf=b''
    t=time.time()
    while time.time()-t<wait:
        rr,_,_=select.select([master],[],[],0.1)
        if rr:
            try: d=os.read(master,1<<20)
            except OSError: break
            if not d: break
            buf+=d
    tm=Term(cols,rows); tm.feed(buf)
    print('===',label,'len',len(buf))
    for i in range(rows):
        s=''.join(c for c,_ in tm.grid[i])
        if s.strip(): print(f"{i:3d}|{s.rstrip()[:110]}")
    try: os.kill(pid,9); os.waitpid(pid,0)
    except Exception: pass
    os.close(master)
    return buf
