import sys,time
sys.path.insert(0,'/tmp/h')
from h import App
from keys import seqs
def make(args,cols=120,rows=40,cwd='/workspace',exe='/workspace/executable'):
    a=App([exe]+args,cols,rows,cwd=cwd); a.read(0.5); return a
def sel(a,row=37): return ''.join(c for c,_ in a.term.grid[row]).rstrip()
def hl(a,white=True):
    tgt=('rgb',250,250,250) if white else ('rgb',65,65,65)
    for r in range(3,40):
        for x,(c,st) in enumerate(a.term.grid[r]):
            if st and st[1]==tgt: return (r,x)
    return None
