{"command": "mkdir -p /workspace/src && cat > /workspace/src/main.rs <<'RSEOF'
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::io;
use std::time::{Duration, Instant};

use clap::Parser;
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use crossterm::execute;
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Alignment, Constraint, Layout, Rect};
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};
use ratatui::widgets::{Block, Borders, Widget};
use ratatui::{Frame, Terminal};

/// Profile data filename
#[derive(Parser, Debug)]
#[command(name = "flamelens", version = "0.3.1")]
struct Args {
    filename: Option<String>,
    /// Whether to sort the stacks by time spent
    #[arg(long)]
    sorted: bool,
    /// Print data to stdout on exit. Useful when piping to other tools
    #[arg(long)]
    echo: bool,
    /// Show debug info
    #[arg(long)]
    debug: bool,
}

// ---------------------------------------------------------------------------
// colors
// ---------------------------------------------------------------------------

const FG_DARK: Color = Color::Rgb(10, 10, 10);
const FG_LIGHT: Color = Color::Rgb(225, 225, 225);
const BG_SELECTED: Color = Color::Rgb(250, 250, 250);
const BG_MATCH: Color = Color::Rgb(10, 35, 150);
const FG_MATCH: Color = Color::Rgb(225, 10, 10);
const BG_TABLE_SEL: Color = Color::Rgb(65, 65, 65);
const ACCENT: Color = Color::Indexed(3);
const DIM: f32 = 0.4;

fn frame_color(path: &str) -> Color {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    path.hash(&mut h);
    let v = h.finish();
    let t = v as f64 / u64::MAX as f64;
    Color::Rgb(
        (205.0 + 50.0 * t) as u8,
        (230.0 * t) as u8,
        (55.0 * t) as u8,
    )
}

fn dim(c: Color) -> Color {
    match c {
        Color::Rgb(r, g, b) => Color::Rgb(
            (r as f32 * DIM) as u8,
            (g as f32 * DIM) as u8,
            (b as f32 * DIM) as u8,
        ),
        other => other,
    }
}

fn contrast(bg: Color) -> Color {
    let (r, g, b) = match bg {
        Color::Rgb(r, g, b) => (r, g, b),
        _ => (0, 0, 0),
    };
    let lum = 0.2126 * r as f32 + 0.7152 * g as f32 + 0.0722 * b as f32;
    if lum > 128.0 {
        FG_DARK
    } else {
        FG_LIGHT
    }
}

fn pct(part: f64, total: f64) -> String {
    let v = part / total * 100.0;
    format!("{:.2}%", v)
}

// ---------------------------------------------------------------------------
// profile tree
// ---------------------------------------------------------------------------

struct Node {
    name: String,
    path: String,
    count: u64,
    own: u64,
    depth: usize,
    pre: usize,
    children: Vec<usize>,
}

struct Tree {
    nodes: Vec<Node>,
    by_name: HashMap<String, Vec<usize>>,
    /// nodes sorted for display: (depth, pre-order index)
    order: Vec<usize>,
