    let v = h.finish();
    let t = v as f64 / u64::MAX as f64;
    Color::Rgb(
        (205.0 + 50.0 * t) as u8,
        (230.0 * t) as u8,
        (55.0 * t) as u8,
    )
}

fn dim(c: Color) -> Color {
    match c {
        Color::Rgb(r, g, b) => Color::Rgb(
            (r as f32 * DIM) as u8,
            (g as f32 * DIM) as u8,
            (b as f32 * DIM) as u8,
        ),
        other => other,
    }
}

