    };
    let lum = 0.2126 * r as f32 + 0.7152 * g as f32 + 0.0722 * b as f32;
    if lum > 128.0 {
        FG_DARK
    } else {
        FG_LIGHT
    }
}

fn pct(part: f64, total: f64) -> String {
    let v = part / total * 100.0;
    format!("{:.2}%", v)
