struct Node {
    name: String,
    path: String,
    count: u64,
    own: u64,
    depth: usize,
    pre: usize,
    children: Vec<usize>,
}

struct Tree {
    nodes: Vec<Node>,
    by_name: HashMap<String, Vec<usize>>,
    /// nodes sorted for display: (depth, pre-order index)
    order: Vec<usize>,
}

impl Tree {
    fn build(data: &str, sorted: bool) -> Tree {
        let mut nodes: Vec<Node> = Vec::new();
        let mut index: HashMap<String, usize> = HashMap::new();
        // root
        nodes.push(Node {
            name: "all".to_string(),
            path: "all".to_string(),
            count: 0,
            own: 0,
            depth: 0,
            pre: 0,
            children: Vec::new(),
        });
        for raw in data.split('\n') {
            let line = raw;
            let Some((name_part, cnt)) = line.rsplit_once(' ') else {
                continue;
            };
            let Ok(count) = cnt.parse::<u64>() else {
                continue;
            };
            let mut cur = 0usize;
            let mut prefix = String::new();
            let parts: Vec<&str> = name_part.split(';').collect();
            for (i, part) in parts.iter().enumerate() {
                if i > 0 {
                    prefix.push(';');
                }
                prefix.push_str(part);
                let next = if let Some(&ix) = index.get(&prefix) {
                    ix
                } else {
                    let ix = nodes.len();
                    nodes.push(Node {
                        name: (*part).to_string(),
                        path: prefix.clone(),
                        count: 0,
                        own: 0,
                        depth: i + 1,
                        pre: 0,
                        children: Vec::new(),
                    });
                    index.insert(prefix.clone(), ix);
                    nodes[cur].children.push(ix);
                    ix
                };
                nodes[next].count += count;
                cur = next;
            }
        }
        // own
        for i in 0..nodes.len() {
            let kids: u64 = nodes[i].children.iter().map(|&c| nodes[c].count).sum();
            nodes[i].own = nodes[i].count.saturating_sub(kids);
        }
        if sorted {
            for i in 0..nodes.len() {
                let mut kids = nodes[i].children.clone();
                kids.sort_by_key(|&c| nodes[c].count);
                kids.reverse();
                nodes[i].children = kids;
            }
        }
        // pre-order index
        let mut pre = 0usize;
        fn walk(nodes: &mut [Node], ix: usize, pre: &mut usize) {
            nodes[ix].pre = *pre;
            *pre += 1;
            let kids = nodes[ix].children.clone();
            for k in kids {
                walk(nodes, k, pre);
            }
        }
        walk(&mut nodes, 0, &mut pre);
        let mut by_name: HashMap<String, Vec<usize>> = HashMap::new();
        for i in 0..nodes.len() {
            by_name.entry(nodes[i].name.clone()).or_default().push(i);
        }
        let mut order: Vec<usize> = (0..nodes.len()).collect();
        order.sort_by_key(|&i| (nodes[i].depth, nodes[i].pre));
        Tree {
            nodes,
            by_name,
            order,
        }
    }

    fn total(&self) -> u64 {
        self.nodes[0].count
    }
}

// ---------------------------------------------------------------------------
// flamegraph layout
// ---------------------------------------------------------------------------

struct FrameBar {
    node: usize,
    x: u16,
    w: u16,
    dimmed: bool,
}

fn collect_bars(tree: &Tree, zoom: Option<usize>, width: u16, depth_from: usize, rows: usize)
    -> Vec<Vec<FrameBar>>
{
    let total = match zoom {
        Some(z) => tree.nodes[z].count,
        None => tree.nodes[0].count,
    };
    let mut levels: Vec<Vec<FrameBar>> = Vec::new();
    if rows == 0 {
        return levels;
    }
    // Determine which nodes are visible: ancestors of zoom (+root) and the subtree of zoom.
    let mut visible: Vec<bool> = vec![false; tree.nodes.len()];
    if let Some(z) = zoom {
        visible[0] = true;
        let mut cur = z;
        loop {
            visible[cur] = true;
            let p = tree.nodes[cur].depth;
            if p == 0 {
                break;
            }
            // find parent
            let mut parent = None;
            // walk up via pre-order: parent is unknown; store parent pointers instead
            break;
        }
        let _ = cur;
    } else {
        for i in 0..tree.nodes.len() {
            visible[i] = true;
        }
    }
    // group by depth
    let mut by_depth: HashMap<usize, Vec<usize>> = HashMap::new();
    for &i in &tree.order {
        if visible[i] {
            by_depth.entry(tree.nodes[i].depth).or_default().push(i);
        }
    }
    let max_depth = *by_depth.keys().max().unwrap_or(&0);
    for d in depth_from..=max_depth {
        if levels.len() >= rows {
            break;
        }
        let mut x: u16 = 0;
        let mut bars: Vec<FrameBar> = Vec::new();
        if let Some(list) = by_depth.get(&d) {
            for &i in list {
                let c = tree.nodes[i].count;
                let w = if tree.nodes[i].depth == 0 {
                    width
                } else if Some(i) == zoom {
                    width
                } else {
                    (c as f64 / total as f64 * width as f64) as u16
                };
                bars.push(FrameBar {
                    node: i,
                    x,
                    w,
                    dimmed: zoom.is_some() && Some(i) != zoom,
                });
                x += w;
            }
        }
        levels.push(bars);
    }
    levels
}

