#[derive(Clone, Copy, PartialEq)]
enum View {
    Flamegraph,
    Table,
}

enum Bottom {
    Selected,
    Match,
    Info,
    Search,
}

struct Timings {
    map: HashMap<&'static str, Duration>,
}

struct App {
    tree: Tree,
    args: Args,
    view: View,
    cursor: usize,
    zoom: Option<usize>,
    scroll: usize,
    table_scroll: usize,
    pattern: Option<Regex>,
    pattern_src: Option<String>,
    input: Option<String>,
    info: Option<String>,
    sort_by_total: bool,
    match_index: usize,
    timings: HashMap<&'static str, Duration>,
}

impl App {
    fn new(tree: Tree, args: Args) -> App {
        App {
            tree,
            args,
            view: View::Flamegraph,
            cursor: 0,
            zoom: None,
            scroll: 0,
            table_scroll: 0,
            pattern: None,
            pattern_src: None,
            input: None,
            info: None,
            sort_by_total: false,
            match_index: 0,
            timings: HashMap::new(),
        }
    }

    fn bottom_blocks(&self) -> Vec<Bottom> {
        if self.input.is_some() {
            return vec![Bottom::Search];
        }
        let mut v = Vec::new();
        if self.pattern.is_some() {
            v.push(Bottom::Match);
        }
        if self.view == View::Flamegraph {
            v.push(Bottom::Selected);
        }
        if self.info.is_some() {
            v.push(Bottom::Info);
        }
        v
    }

    fn title_lines(&self, w: u16) -> usize {
        if w <= 40 {
            return 0;
        }
        let avail = (w - 40) as usize;
        let c = self.center_title().chars().count();
        (c + avail - 1) / avail
    }

    fn center_title(&self) -> String {
        match &self.args.filename {
            Some(f) => f.clone(),
            None => "stdin".to_string(),
        }
    }

    fn left_title(&self) -> Vec<Span<'static>> {
        let active = if self.view == View::Flamegraph { 0 } else { 1 };
        let names = ["Flamegraph", "Top"];
        let mut spans: Vec<Span<'static>> = vec![Span::raw(" ")];
        for (i, n) in names.iter().enumerate() {
            if i > 0 {
                spans.push(Span::raw(" | "));
            }
            if i == active {
                spans.push(Span::styled(
                    format!("[{}]", n),
                    Style::new().bold().fg(ACCENT),
                ));
            } else {
                spans.push(Span::styled((*n).to_string(), Style::new().bold()));
            }
        }
        spans
    }
}

