struct Node {
    name: String,
    path: String,
    count: u64,
    own: u64,
    depth: usize,
    pre: usize,
    parent: usize,
    children: Vec<usize>,
    color: Color,
}

struct Tree {
    nodes: Vec<Node>,
    by_name: Vec<(String, Vec<usize>)>,
    /// node indices grouped by depth, in display order
    levels: Vec<Vec<usize>>,
}

impl Tree {
    fn build(data: &str, sorted: bool) -> Tree {
        let mut nodes: Vec<Node> = Vec::new();
        let mut index: HashMap<String, usize> = HashMap::new();
        nodes.push(Node {
            name: "all".to_string(),
            path: "all".to_string(),
            count: 0,
            own: 0,
            depth: 0,
            pre: 0,
            parent: 0,
            children: Vec::new(),
            color: frame_color("all"),
        });
        for line in data.split('\n') {
            let Some((name_part, cnt)) = line.rsplit_once(' ') else {
                continue;
            };
            let Ok(count) = cnt.parse::<u64>() else {
                continue;
            };
            let mut cur = 0usize;
            let mut prefix = String::new();
            for (i, part) in name_part.split(';').enumerate() {
                if i > 0 {
                    prefix.push(';');
                }
                prefix.push_str(part);
                let next = match index.get(&prefix) {
                    Some(&ix) => ix,
                    None => {
                        let ix = nodes.len();
                        nodes.push(Node {
                            name: part.to_string(),
                            path: prefix.clone(),
                            count: 0,
                            own: 0,
                            depth: i + 1,
                            pre: 0,
                            parent: cur,
                            children: Vec::new(),
                            color: frame_color(&prefix),
                        });
                        index.insert(prefix.clone(), ix);
                        nodes[cur].children.push(ix);
                        ix
                    }
                };
                nodes[next].count += count;
                cur = next;
            }
        }
        for i in 0..nodes.len() {
            let kids: u64 = nodes[i].children.iter().map(|&c| nodes[c].count).sum();
            nodes[i].own = nodes[i].count.saturating_sub(kids);
        }
        if sorted {
            for i in 0..nodes.len() {
                let mut kids = nodes[i].children.clone();
                kids.sort_by_key(|&c| nodes[c].count);
                kids.reverse();
                nodes[i].children = kids;
            }
        }
        let mut pre = 0usize;
        fn walk(nodes: &mut [Node], ix: usize, pre: &mut usize) {
            nodes[ix].pre = *pre;
            *pre += 1;
            let kids = nodes[ix].children.clone();
            for k in kids {
                walk(nodes, k, pre);
            }
        }
        walk(&mut nodes, 0, &mut pre);
        let mut maxd = 0usize;
        for n in &nodes {
            maxd = maxd.max(n.depth);
