        };
        let mut out: Vec<Span<'static>> = vec![Span::raw(" ")];
        for (i, (key, rest)) in keys.iter().enumerate() {
            if i > 0 {
                out.push(Span::raw(" "));
            }
            out.push(Span::raw("["));
            out.push(Span::styled(
                (*key).to_string(),
                Style::new().bold().fg(ACCENT),
            ));
            out.push(Span::raw(format!(":{}]", rest)));
        }
        out.push(Span::raw(" ["));
        out.push(Span::styled("q", Style::new().bold().fg(ACCENT)));
        out.push(Span::raw(":quit]"));
        out
    }

    fn table_rows(&self) -> Vec<Row> {
        let mut rows: Vec<Row> = Vec::new();
        for (name, list) in &self.tree.by_name {
            let mut total = 0u64;
            let mut own = 0u64;
            for &i in list {
                total += self.tree.nodes[i].count;
                own += self.tree.nodes[i].own;
            }
            rows.push(Row {
                name: name.clone(),
                total,
                own,
            });
        }
        if self.sort_by_total {
            rows.sort_by_key(|r| std::cmp::Reverse(r.total));
        } else {
            rows.sort_by_key(|r| std::cmp::Reverse(r.own));
        }
        rows
    }

    fn widths(&self, total: u64, w: u16) -> Vec<u16> {
        let mut v = vec![0u16; self.tree.nodes.len()];
        for i in 0..self.tree.nodes.len() {
            let n = &self.tree.nodes[i];
            v[i] = if n.depth == 0 {
                w
            } else {
                (n.count as f64 / total as f64 * w as f64) as u16
            };
        }
        v
    }
}

// ---------------------------------------------------------------------------
// rendering
// ---------------------------------------------------------------------------

fn hline(buf: &mut ratatui::buffer::Buffer, x: u16, y: u16, w: u16) {
    for i in 0..w {
        if x + i < buf.area.width {
            buf[(x + i, y)].set_symbol(HLINE);
        }
    }
}

fn render(f: &mut Frame, app: &mut App) {
    let area = f.area();
    let w = area.width;
    let buf = f.buffer_mut();
    let panels = app.bottom_panels();
    let bottom_h = 2 * panels.len() as u16;
    let main_avail = area.height.saturating_sub(2 + bottom_h);
    let tl = app.title_lines(w) as u16;
    let header_h = (2 + tl).min(main_avail).max(2);
    let main_h = main_avail.saturating_sub(header_h);
    app.main_h = main_h;

    // ---- header ----
    hline(buf, area.x, area.y, w);
    if header_h >= 3 {
        hline(buf, area.x, area.y + header_h - 1, w);
    }
    let title_y = area.y + 1;
    let mut x = 0u16;
    for s in left_title(app.view) {
        for (i, ch) in s.content.chars().enumerate() {
            if x + i as u16 < w {
                let c = &mut buf[(area.x + x + i as u16, title_y)];
                c.set_symbol(&ch.to_string());
                c.set_style(s.style);
            }
        }
        x += s.content.chars().count() as u16;
    }
    let right = "flamelens v0.3.1";
    let rw = right.chars().count() as u16;
    if w > rw {
        for (i, ch) in right.chars().enumerate() {
            let c = &mut buf[(area.x + w - rw + i as u16, title_y)];
            c.set_symbol(&ch.to_string());
            c.set_style(Style::new().bold());
        }
    }
    let ct = app.center_title();
    let rect_w = w.saturating_sub(36);
    let rect_h = if header_h >= 3 { header_h - 2 } else { 1 };
    if rect_w > 0 && rect_h > 0 {
        let chars: Vec<char> = ct.chars().collect();
        let n = chars.len();
        let mut consumed = 0usize;
        let mut row = 0u16;
        while consumed < n && row < rect_h {
            let chunk = (n - consumed).min(rect_w as usize);
            let s: String = chars[consumed..consumed + chunk].iter().collect();
            let off = ((rect_w as usize).saturating_sub(chunk) + 1) / 2;
            let sx = 20u16.saturating_add(off as u16);
            for (i, ch) in s.chars().enumerate() {
                let cx = area.x + sx + i as u16;
                if cx < area.x + w {
                    let c = &mut buf[(cx, title_y + row)];
                    c.set_symbol(&ch.to_string());
                    c.set_style(Style::new().bold());
                }
            }
            consumed += chunk;
            row += 1;
        }
    }

    // ---- main ----
    let main_y = area.y + header_h;
    match app.view {
        View::Flamegraph => render_flamegraph(f, app, Rect::new(area.x, main_y, w, main_h)),
        View::Table => render_table(f, app, Rect::new(area.x, main_y, w, main_h)),
    }

    // ---- bottom panels ----
    let mut y = main_y + main_h;
    for (title, content) in panels {
        let tlen = title.chars().count() as u16;
        for (i, ch) in title.chars().enumerate() {
            let c = &mut buf[(area.x + i as u16, y)];
            c.set_symbol(&ch.to_string());
            c.set_style(Style::new().bold().fg(ACCENT));
        }
        for xx in tlen..w {
            buf[(area.x + xx, y)].set_symbol(HLINE);
        }
        for (i, ch) in content.chars().enumerate() {
            if i as u16 < w {
                buf[(area.x + i as u16, y + 1)].set_symbol(&ch.to_string());
            }
        }
        y += 2;
    }

    // ---- separator + footer ----
    hline(buf, area.x, y, w);
    let footer = app.footer();
    let fl: usize = footer.iter().map(|s| s.content.chars().count()).sum();
    let fx = if (fl as u16) < w { (w - fl as u16) / 2 } else { 0 };
    let mut cx = fx;
    let fy = area.y + area.height - 1;
    for s in footer {
        for ch in s.content.chars() {
            if cx < w {
                let c = &mut buf[(area.x + cx, fy)];
                c.set_symbol(&ch.to_string());
                c.set_style(s.style);
            }
            cx += 1;
        }
    }
}

fn left_title(view: View) -> Vec<Span<'static>> {
    let active = if view == View::Flamegraph { 0 } else { 1 };
    let names = ["Flamegraph", "Top"];
    let mut spans: Vec<Span<'static>> = vec![Span::raw(" ")];
    for (i, n) in names.iter().enumerate() {
        if i > 0 {
            spans.push(Span::raw(" | "));
        }
        if i == active {
            spans.push(Span::styled(
                format!("[{}]", n),
                Style::new().bold().fg(ACCENT),
            ));
        } else {
            spans.push(Span::styled((*n).to_string(), Style::new().bold()));
        }
    }
    spans
}

fn render_flamegraph(f: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 || area.width == 0 {
        return;
    }
    let tree = &app.tree;
    let zoom = app.zoom;
    let total = match zoom {
        Some(z) => tree.nodes[z].count,
        None => tree.nodes[0].count,
    };
    let maxd = tree.levels.len().saturating_sub(1);
    let buf = f.buffer_mut();
    let start = app.scroll as usize;
    for row in 0..area.height as usize {
        let d = start + row;
        if d > maxd {
            break;
        }
        let mut x: u16 = 0;
        for &ix in &tree.levels[d] {
            if !tree.visible(zoom, ix) {
                continue;
            }
            let node = &tree.nodes[ix];
            let bw = if node.depth == 0 || Some(ix) == zoom {
                area.width
            } else {
                (node.count as f64 / total as f64 * area.width as f64) as u16
            };
            if bw == 0 {
                continue;
            }
            let dimmed = zoom.is_some() && node.depth != 0 && Some(ix) != zoom;
            let mut bg = node.color;
            if dimmed {
                bg = dim(bg);
            }
            let selected = ix == app.cursor;
            let matched = app
                .pattern
                .as_ref()
                .map(|r| r.is_match(&node.name))
                .unwrap_or(false);
            if selected {
                bg = BG_SELECTED;
            } else if matched {
                bg = BG_MATCH;
            }
            let fg = contrast(bg);
            let mut ranges: Vec<(usize, usize)> = Vec::new();
            if matched {
                if let Some(r) = app.pattern.as_ref() {
                    for m in r.find_iter(&node.name) {
                        ranges.push((m.start(), m.end()));
                    }
                }
            }
            if bw == 1 {
                let c = &mut buf[(area.x + x, area.y + row as u16)];
                c.set_symbol(".");
                c.set_fg(fg);
                c.set_bg(bg);
            } else {
                let label: Vec<char> = format!(" {}", node.name).chars().collect();
                for i in 0..bw as usize {
                    let ch = if i < label.len() { label[i] } else { ' ' };
                    let name_idx = i as i64 - 1;
                    let is_m = name_idx >= 0
                        && ranges
                            .iter()
                            .any(|&(a, b)| (name_idx as usize) >= a && (name_idx as usize) < b);
                    let cell = &mut buf[(area.x + x + i as u16, area.y + row as u16)];
                    cell.set_symbol(&ch.to_string());
                    cell.set_fg(if is_m { FG_MATCH } else { fg });
                    cell.set_bg(bg);
                }
            }
            x += bw;
        }
    }
}

fn render_table(f: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 || area.width == 0 {
        return;
    }
    let buf = f.buffer_mut();
    let rows = app.table_rows();
    let n = rows.len();
    let hdr = if app.sort_by_total {
        format!("{:<15}{:<15}{}", format!("Total [{}]", DOWN), "Own", "Name")
    } else {
        format!("{:<15}{:<15}{}", "Total", format!("Own [{}]", DOWN), "Name")
    };
    for (i, ch) in hdr.chars().enumerate() {
        if (i as u16) < area.width {
            let c = &mut buf[(area.x + i as u16, area.y)];
            c.set_symbol(&ch.to_string());
            c.set_style(Style::new().bold().reversed());
        }
    }
    for xx in hdr.chars().count() as u16..area.width {
        let c = &mut buf[(area.x + xx, area.y)];
        c.set_style(Style::new().bold().reversed());
    }
    let h = (area.height - 1) as usize;
    if app.table_cursor < app.table_scroll {
        app.table_scroll = app.table_cursor;
    } else if app.table_cursor >= app.table_scroll + h {
        app.table_scroll = app.table_cursor + 1 - h;
    }
    let base = app.tree.nodes[0].count as f64;
    for r in 0..(area.height as usize - 1) {
        let idx = app.table_scroll + r;
        if idx >= n {
            break;
        }
        let row = &rows[idx];
        let t = format!(
            "{:<15}{:<15}{}",
            format!("{} ({})", row.total, pct_str(row.total as f64, base)),
            format!("{} ({})", row.own, pct_str(row.own as f64, base)),
            row.name
        );
        let sel = idx == app.table_cursor;
        for (i, ch) in t.chars().enumerate() {
            if (i as u16) >= area.width {
                break;
            }
            let c = &mut buf[(area.x + i as u16, area.y + 1 + r as u16)];
            c.set_symbol(&ch.to_string());
            if sel {
                c.set_bg(BG_TABLE_SEL);
            }
        }
        if sel {
            for xx in t.chars().count() as u16..area.width {
                buf[(area.x + xx, area.y + 1 + r as u16)].set_bg(BG_TABLE_SEL);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// key handling
// ---------------------------------------------------------------------------

fn flame_heights(app: &App) -> (u64, u16, u16) {
    let total = match app.zoom {
        Some(z) => app.tree.nodes[z].count,
        None => app.tree.nodes[0].count,
    };
    (total, app.main_h, app.tree.levels.len().saturating_sub(1) as u16)
}

fn handle_key(app: &mut App, key: KeyEvent) {
    if let Some(inp) = app.input.as_mut() {
        match key.code {
            KeyCode::Esc => {
                app.input = None;
            }
            KeyCode::Enter => {
                let src = inp.clone();
                app.input = None;
                match regex::Regex::new(&src) {
                    Ok(r) => {
                        app.pattern = Some(r);
                        app.pattern_src = Some(src);
                        app.info = None;
                    }
                    Err(_) => {
                        app.pattern = None;
                        app.pattern_src = None;
                        app.info = Some(format!("Invalid regex: {}", src));
                    }
                }
            }
            KeyCode::Backspace => {
                inp.pop();
            }
            KeyCode::Char(c) => inp.push(c),
            _ => {}
        }
        return;
    }
    match key.code {
        KeyCode::Char('q') => app.quit = true,
        KeyCode::Char('c')
            if key
                .modifiers
                .contains(crossterm::event::KeyModifiers::CONTROL) =>
        {
            app.quit = true
        }
        KeyCode::Esc => {
            if app.zoom.is_some() {
                app.zoom = None;
            }
        }
        KeyCode::Tab => {
            app.view = if app.view == View::Flamegraph {
                View::Table
            } else {
                View::Flamegraph
            };
        }
        KeyCode::Char('r') => {
            app.zoom = None;
            app.scroll = 0;
            app.table_scroll = 0;
            app.table_cursor = 0;
            app.pattern = None;
            app.pattern_src = None;
            app.info = None;
            app.cursor = 0;
            app.view = View::Flamegraph;
        }
        KeyCode::Enter => {
            if app.view == View::Flamegraph {
                app.zoom = Some(app.cursor);
            }
        }
        KeyCode::Char('f') => {
            let h = app.main_h;
            if app.view == View::Flamegraph {
                let (_t, _mh, maxl) = flame_heights(app);
                let max = (maxl as usize).saturating_sub(h as usize);
                app.scroll = (app.scroll as usize + h as usize).min(max) as u16;
            } else {
                let n = app.table_rows().len();
                app.table_scroll =
                    (app.table_scroll as usize + h as usize).min(n.saturating_sub(1)) as u16;
            }
        }
        KeyCode::Char('b') => {
            let h = app.main_h;
            if app.view == View::Flamegraph {
                app.scroll = app.scroll.saturating_sub(h);
            } else {
                app.table_scroll = app.table_scroll.saturating_sub(h);
            }
        }
        KeyCode::Char('g') => {
            if app.view == View::Flamegraph {
                app.scroll = 0;
            }
        }
        KeyCode::Char('G') => {
            if app.view == View::Flamegraph {
                let (_t, mh, maxl) = flame_heights(app);
                app.scroll = (maxl as usize).saturating_sub(mh as usize) as u16;
            }
        }
        KeyCode::Char('/') => app.input = Some(String::new()),
        KeyCode::Char('#') => {
            let name = app.tree.nodes[app.cursor].name.clone();
            let src = format!("^{}$", name);
            match regex::Regex::new(&src) {
                Ok(r) => {
                    app.pattern = Some(r);
                    app.pattern_src = Some(src);
                    app.info = None;
                }
                Err(_) => {
                    app.pattern = None;
                    app.pattern_src = None;
                    app.info = Some(format!("Invalid regex: {}", src));
                }
            }
        }
        KeyCode::Char('n') => jump_match(app, 1),
        KeyCode::Char('N') => jump_match(app, -1),
        KeyCode::Char('1') => {
            if app.view == View::Table {
                app.sort_by_total = true;
            }
        }
        KeyCode::Char('2') => {
            if app.view == View::Table {
                app.sort_by_total = false;
            }
        }
        KeyCode::Char('j') | KeyCode::Down => {
            if app.view == View::Flamegraph {
                move_down(app);
            } else {
                let n = app.table_rows().len();
                if app.table_cursor + 1 < n {
                    app.table_cursor += 1;
                }
            }
        }
        KeyCode::Char('k') | KeyCode::Up => {
            if app.view == View::Flamegraph {
                move_up(app);
            } else {
                app.table_cursor = app.table_cursor.saturating_sub(1);
            }
        }
        KeyCode::Char('h') | KeyCode::Left => {
            if app.view == View::Flamegraph {
                move_side(app, -1);
            }
        }
        KeyCode::Char('l') | KeyCode::Right => {
            if app.view == View::Flamegraph {
                move_side(app, 1);
            }
        }
        _ => {}
    }
    if app.view == View::Flamegraph {
        follow_cursor(app);
    } else {
        let h = (app.main_h as usize).saturating_sub(1);
        let n = app.table_rows().len();
        if n == 0 || h == 0 {
            return;
        }
        if app.table_cursor < app.table_scroll {
            app.table_scroll = app.table_cursor;
        } else if app.table_cursor >= app.table_scroll + h {
            app.table_scroll = app.table_cursor + 1 - h;
        }
        let _ = n;
    }
}

fn follow_cursor(app: &mut App) {
    let h = app.main_h as usize;
    if h == 0 {
        return;
    }
    let cd = app.tree.nodes[app.cursor].depth;
    if cd < app.scroll as usize {
        app.scroll = cd as u16;
    } else if cd >= app.scroll as usize + h {
        app.scroll = (cd - h + 1) as u16;
    }
}

fn move_down(app: &mut App) {
    let node = &app.tree.nodes[app.cursor];
    if node.children.is_empty() {
        return;
    }
    let best = *node
        .children
        .iter()
        .max_by_key(|&c| app.tree.nodes[*c].count)
        .unwrap();
    app.cursor = best;
}

fn move_up(app: &mut App) {
    let node = &app.tree.nodes[app.cursor];
    if node.depth == 0 {
        return;
    }
    app.cursor = node.parent;
}

fn move_side(app: &mut App, dir: i32) {
    let parent = app.tree.nodes[app.cursor].parent;
    let kids = app.tree.nodes[parent].children.clone();
    let pos = match kids.iter().position(|&k| k == app.cursor) {
        Some(p) => p,
        None => return,
    };
    let total = match app.zoom {
        Some(z) => app.tree.nodes[z].count,
        None => app.tree.nodes[0].count,
    };
    let w = app.widths(total, app.main_w);
    let mut p = pos as i64;
    loop {
        p += dir as i64;
        if p < 0 || p >= kids.len() as i64 {
            return;
        }
        if w[kids[p as usize]] > 0 {
            app.cursor = kids[p as usize];
            return;
        }
    }
}

fn jump_match(app: &mut App, dir: i32) {
    let rx = match app.pattern.clone() {
        Some(r) => r,
        None => return,
    };
    let total = match app.zoom {
        Some(z) => app.tree.nodes[z].count,
        None => app.tree.nodes[0].count,
    };
    let w = app.widths(total, app.main_w);
    let mut list: Vec<usize> = Vec::new();
    for &i in app.tree.levels.iter().flat_map(|l| l.iter()) {
        if w[i] > 0 && rx.is_match(&app.tree.nodes[i].name) {
            list.push(i);
        }
    }
    if list.is_empty() {
        return;
    }
    match list.iter().position(|&i| i == app.cursor) {
        Some(p) => {
            let np = p as i64 + dir as i64;
            if np >= 0 && (np as usize) < list.len() {
                app.cursor = list[np as usize];
            }
        }
        None => {
            if dir > 0 {
                app.cursor = list[0];
            }
        }
    }
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

fn main() {
    let args = Args::parse();
    let data = match &args.filename {
        Some(f) => std::fs::read_to_string(f).expect("Could not read file"),
        None => {
            let mut s = String::new();
            io::stdin().read_to_string(&mut s).unwrap_or_default();
            s
        }
    };
    let tree = Tree::build(&data, args.sorted);
    if let Err(_e) = run_app(tree, args, &data) {
        std::process::exit(1);
    }
}

fn run_app(tree: Tree, args: Args, data: &str) -> io::Result<()> {
    crossterm::terminal::enable_raw_mode()?;
    let mut stderr = io::stderr();
    execute!(
        stderr,
        crossterm::terminal::EnterAlternateScreen,
        crossterm::cursor::Hide
    )?;
    let backend = CrosstermBackend::new(stderr);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;
    let mut app = App::new(tree, args);
    app.main_w = terminal.size()?.width;
    let mut last_tick = Instant::now();
    loop {
        terminal.draw(|f| render(f, &mut app))?;
        let timeout = Duration::from_millis(100).saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    let t0 = Instant::now();
                    handle_key(&mut app, key);
                    app.timings.insert("handle_key_events", t0.elapsed());
                }
            }
        }
        if last_tick.elapsed() >= Duration::from_millis(100) {
            last_tick = Instant::now();
        }
        if app.quit {
            break;
        }
    }
    crossterm::terminal::disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        crossterm::terminal::LeaveAlternateScreen,
        event::DisableMouseCapture
    )?;
    terminal.show_cursor()?;
    if args.echo {
        println!("{}", data);
    }
    Ok(())
}
