use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::io;
use std::time::{Duration, Instant};

use clap::Parser;
use crossterm::event::{self, Event, KeyCode, KeyEventKind};
use crossterm::execute;
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Alignment, Position, Rect};
use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span};
use ratatui::{Frame, Terminal};

const HLINE: &str = "\u{2500}";
const DOWN: &str = "\u{25bc}";

/// Profile data filename
#[derive(Parser, Debug)]
#[command(name = "flamelens", version = "0.3.1")]
struct Args {
    filename: Option<String>,
    /// Whether to sort the stacks by time spent
    #[arg(long)]
    sorted: bool,
    /// Print data to stdout on exit. Useful when piping to other tools
    #[arg(long)]
    echo: bool,
    /// Show debug info
    #[arg(long)]
