// ---------------------------------------------------------------------------
// colors
// ---------------------------------------------------------------------------

const FG_DARK: Color = Color::Rgb(10, 10, 10);
const FG_LIGHT: Color = Color::Rgb(225, 225, 225);
const BG_SELECTED: Color = Color::Rgb(250, 250, 250);
const BG_MATCH: Color = Color::Rgb(10, 35, 150);
const FG_MATCH: Color = Color::Rgb(225, 10, 10);
const BG_TABLE_SEL: Color = Color::Rgb(65, 65, 65);
const ACCENT: Color = Color::Indexed(3);
const DIM: f32 = 0.4;

fn frame_color(path: &str) -> Color {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    path.hash(&mut h);
    let v = h.finish();
    let t = v as f64 / u64::MAX as f64;
    Color::Rgb((205.0 + 50.0 * t) as u8, (230.0 * t) as u8, (55.0 * t) as u8)
}

fn dim(c: Color) -> Color {
    match c {
        Color::Rgb(r, g, b) => Color::Rgb(
            (r as f32 * DIM) as u8,
            (g as f32 * DIM) as u8,
            (b as f32 * DIM) as u8,
        ),
        other => other,
    }
}

fn contrast(bg: Color) -> Color {
    let (r, g, b) = match bg {
        Color::Rgb(r, g, b) => (r, g, b),
        _ => (0, 0, 0),
    };
    let lum = 0.2126 * r as f32 + 0.7152 * g as f32 + 0.0722 * b as f32;
    if lum > 128.0 {
        FG_DARK
    } else {
        FG_LIGHT
    }
}

fn pct_str(part: f64, total: f64) -> String {
    format!("{:.2}%", part / total * 100.0)
}

// ---------------------------------------------------------------------------
// profile tree
// ---------------------------------------------------------------------------

struct Node {
    name: String,
    path: String,
    count: u64,
    own: u64,
    depth: usize,
    pre: usize,
    parent: usize,
    children: Vec<usize>,
    color: Color,
}

struct Tree {
    nodes: Vec<Node>,
    by_name: Vec<(String, Vec<usize>)>,
    levels: Vec<Vec<usize>>,
}

impl Tree {
    fn build(data: &str, sorted: bool) -> Tree {
        let mut nodes: Vec<Node> = Vec::new();
        let mut index: HashMap<String, usize> = HashMap::new();
        nodes.push(Node {
            name: "all".to_string(),
            path: "all".to_string(),
            count: 0,
            own: 0,
            depth: 0,
            pre: 0,
            parent: 0,
            children: Vec::new(),
            color: frame_color("all"),
        });
        for line in data.split('\n') {
            let Some((name_part, cnt)) = line.rsplit_once(' ') else {
                continue;
            };
            let Ok(count) = cnt.parse::<u64>() else {
                continue;
            };
            let mut cur = 0usize;
            let mut prefix = String::new();
            for (i, part) in name_part.split(';').enumerate() {
                if i > 0 {
                    prefix.push(';');
                }
                prefix.push_str(part);
                let next = match index.get(&prefix) {
                    Some(&ix) => ix,
                    None => {
                        let ix = nodes.len();
                        nodes.push(Node {
                            name: part.to_string(),
                            path: prefix.clone(),
                            count: 0,
                            own: 0,
                            depth: i + 1,
                            pre: 0,
                            parent: cur,
                            children: Vec::new(),
                            color: frame_color(&prefix),
                        });
                        index.insert(prefix.clone(), ix);
                        nodes[cur].children.push(ix);
                        ix
                    }
                };
                nodes[next].count += count;
                cur = next;
            }
        }
        for i in 0..nodes.len() {
            let kids: u64 = nodes[i].children.iter().map(|&c| nodes[c].count).sum();
            nodes[i].own = nodes[i].count.saturating_sub(kids);
        }
        if sorted {
            for i in 0..nodes.len() {
                let mut kids = nodes[i].children.clone();
                kids.sort_by_key(|&c| nodes[c].count);
                kids.reverse();
                nodes[i].children = kids;
            }
        }
        let mut pre = 0usize;
        fn walk(nodes: &mut [Node], ix: usize, pre: &mut usize) {
            nodes[ix].pre = *pre;
            *pre += 1;
            let kids = nodes[ix].children.clone();
            for k in kids {
                walk(nodes, k, pre);
            }
        }
        walk(&mut nodes, 0, &mut pre);
        let mut maxd = 0usize;
        for n in &nodes {
            maxd = maxd.max(n.depth);
        }
        let mut levels: Vec<Vec<usize>> = vec![Vec::new(); maxd + 1];
        for i in 0..nodes.len() {
            levels[nodes[i].depth].push(i);
        }
        for l in levels.iter_mut() {
            l.sort_by_key(|&i| nodes[i].pre);
        }
        let mut tmp: HashMap<String, Vec<usize>> = HashMap::new();
        for i in 0..nodes.len() {
            tmp.entry(nodes[i].name.clone()).or_default().push(i);
        }
        let mut by_name: Vec<(String, Vec<usize>)> = tmp.into_iter().collect();
        by_name.sort_by(|a, b| b.0.cmp(&a.0));
        Tree { nodes, by_name, levels }
    }
    fn total(&self) -> u64 {
        self.nodes[0].count
    }
    fn in_subtree(&self, root: usize, ix: usize) -> bool {
        let mut cur = ix;
        loop {
            if cur == root {
                return true;
            }
            if cur == 0 {
                return false;
            }
            cur = self.nodes[cur].parent;
        }
    }
    fn visible(&self, zoom: Option<usize>, ix: usize) -> bool {
        match zoom {
            None => true,
            Some(z) => ix == 0 || self.in_subtree(z, ix) || self.in_subtree(ix, z),
        }
    }
}

// ---------------------------------------------------------------------------
// app state
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq)]
enum View {
    Flamegraph,
    Table,
}

struct Row {
    name: String,
    total: u64,
    own: u64,
}

struct App {
    tree: Tree,
    args: Args,
    view: View,
    cursor: usize,
    zoom: Option<usize>,
    scroll: usize,
    table_scroll: usize,
    table_cursor: usize,
    pattern: Option<regex::Regex>,
    pattern_src: Option<String>,
    input: Option<String>,
    info: Option<String>,
    sort_by_total: bool,
    main_h: u16,
    main_w: u16,
    timings: HashMap<String, f64>,
    quit: bool,
}

impl App {
    fn new(tree: Tree, args: Args) -> App {
        App {
            tree,
            args,
            view: View::Flamegraph,
            cursor: 0,
            zoom: None,
            scroll: 0,
            table_scroll: 0,
            table_cursor: 0,
            pattern: None,
            pattern_src: None,
            input: None,
            info: None,
            sort_by_total: false,
            main_h: 33,
            main_w: 120,
            timings: HashMap::new(),
            quit: false,
        }
    }

    fn center_title(&self) -> String {
        match &self.args.filename {
            Some(f) => f.clone(),
            None => "stdin".to_string(),
        }
    }

    fn title_lines(&self, w: u16) -> usize {
        if w <= 40 {
            return 0;
        }
        let avail = (w - 40) as usize;
        let c = self.center_title().chars().count();
        (c + avail - 1) / avail
    }

    fn bottom_panels(&self) -> Vec<(String, String)> {
        if let Some(inp) = &self.input {
            return vec![("Search ".to_string(), inp.clone())];
        }
        let mut v: Vec<(String, String)> = Vec::new();
        if let Some(src) = &self.pattern_src {
            let rx = self.pattern.as_ref().unwrap();
            let mut count = 0u64;
            match self.view {
                View::Flamegraph => {
                    for n in &self.tree.nodes {
                        if rx.is_match(&n.name) {
                            count += n.count;
                        }
                    }
                }
                View::Table => {
                    for (name, list) in &self.tree.by_name {
                        if rx.is_match(name) {
                            for &i in list {
                                count += self.tree.nodes[i].count;
                            }
                        }
                    }
                }
            }
            let base = self.tree.nodes[0].count as f64;
            let mut s = format!(
                "\"{}\" [{} samples, {}% of all",
                src,
                count,
                pct_str(count as f64, base)
            );
            if let Some(z) = self.zoom {
                s.push_str(&format!(
                    ", {}% of zoomed",
                    pct_str(count as f64, self.tree.nodes[z].count as f64)
                ));
            }
            s.push(']');
            v.push(("Match ".to_string(), s));
        }
        if self.view == View::Flamegraph {
            let n = &self.tree.nodes[self.cursor];
            let mut s = format!(
                "{} [{} samples, {}% of all",
                n.name,
                n.count,
                pct_str(n.count as f64, self.tree.nodes[0].count as f64)
            );
            if let Some(z) = self.zoom {
                s.push_str(&format!(
                    ", {}% of zoomed",
                    pct_str(n.count as f64, self.tree.nodes[z].count as f64)
                ));
            }
            s.push(']');
            v.push(("Selected ".to_string(), s));
        }
        if let Some(msg) = &self.info {
            v.push(("Info ".to_string(), msg.clone()));
        }
        if self.args.debug {
            let mut parts: Vec<String> = Vec::new();
            for (k, v) in &self.timings {
                parts.push(format!("{}:{:.2}ms", k, v));
            }
            v.push(("Debug ".to_string(), format!("Debug: {}", parts.join(" "))));
        }
        v
    }

    fn footer(&self) -> Vec<Span<'static>> {
        let keys: Vec<(&str, &str)> = match self.view {
            View::Flamegraph => {
                let mut k: Vec<(&str, &str)> = vec![
                    ("hjkl", " move cursor"),
                    ("f/b", " scroll"),
                    ("enter/esc", " zoom"),
                    ("/", " search"),
                    ("#", " search like cursor"),
                ];
                if self.pattern.is_some() {
                    k.push(("n/N", " next/prev search"));
                }
                k.push(("r", " reset"));
                k
            }
            View::Table => vec![
                ("j/k", " move cursor"),
                ("f/b", " scroll"),
                ("1", " sort by total"),
                ("2", " sort by own"),
                ("/", " filter"),
                ("r", " reset"),
            ],
        };
        let mut out: Vec<Span<'static>> = vec![Span::raw(" ")];
        for (i, (key, rest)) in keys.iter().enumerate() {
            if i > 0 {
                out.push(Span::raw(" "));
            }
            out.push(Span::raw("["));
            out.push(Span::styled(
                (*key).to_string(),
                Style::new().bold().fg(ACCENT),
            ));
            out.push(Span::raw(format!(":{}]", rest)));
        }
        out.push(Span::raw(" ["));
        out.push(Span::styled("q", Style::new().bold().fg(ACCENT)));
        out.push(Span::raw(":quit]"));
        out
    }

    fn table_rows(&self) -> Vec<Row> {
        let mut rows: Vec<Row> = Vec::new();
        for (name, list) in &self.tree.by_name {
            let mut total = 0u64;
            let mut own = 0u64;
            for &i in list {
                total += self.tree.nodes[i].count;
                own += self.tree.nodes[i].own;
            }
            rows.push(Row {
                name: name.clone(),
                total,
                own,
            });
        }
        if self.sort_by_total {
            rows.sort_by_key(|r| std::cmp::Reverse(r.total));
        } else {
            rows.sort_by_key(|r| std::cmp::Reverse(r.own));
        }
        rows
    }

    fn zoom_total(&self) -> u64 {
        match self.zoom {
            Some(z) => self.tree.nodes[z].count,
            None => self.tree.nodes[0].count,
        }
    }

    fn widths(&self, total: u64, w: u16) -> Vec<u16> {
        let mut v = vec![0u16; self.tree.nodes.len()];
        for i in 0..self.tree.nodes.len() {
            let n = &self.tree.nodes[i];
            v[i] = if n.depth == 0 {
                w
            } else {
                (n.count as f64 / total as f64 * w as f64) as u16
            };
        }
        v
    }
}

fn left_title(view: View) -> Vec<Span<'static>> {
    let active = if view == View::Flamegraph { 0 } else { 1 };
    let names = ["Flamegraph", "Top"];
    let mut spans: Vec<Span<'static>> = vec![Span::raw(" ")];
    for (i, n) in names.iter().enumerate() {
        if i > 0 {
            spans.push(Span::raw(" | "));
        }
        if i == active {
            spans.push(Span::styled(
                format!("[{}]", n),
                Style::new().bold().fg(ACCENT),
            ));
        } else {
            spans.push(Span::styled((*n).to_string(), Style::new().bold()));
        }
    }
    spans
}

// ---------------------------------------------------------------------------
// rendering
// ---------------------------------------------------------------------------

fn hline(buf: &mut ratatui::buffer::Buffer, x: u16, y: u16, w: u16) {
    for i in 0..w {
        if x + i < buf.area.width {
            buf[(x + i, y)].set_symbol(HLINE);
        }
    }
}

fn put(buf: &mut ratatui::buffer::Buffer, x: u16, y: u16, ch: &str, st: Style) {
    if x >= buf.area.width || y >= buf.area.height {
        return;
    }
    let c = &mut buf[(x, y)];
    c.set_symbol(ch);
    c.set_style(st);
}

fn render(f: &mut Frame, app: &mut App) {
    let area = f.area();
    let w = area.width;
    let buf = f.buffer_mut();
    let panels = app.bottom_panels();
    let bottom_h = 2 * panels.len() as u16;
    let main_avail = area.height.saturating_sub(2 + bottom_h);
    let tl = app.title_lines(w) as u16;
    let header_h = (2 + tl).min(main_avail).max(2);
    let main_h = main_avail.saturating_sub(header_h);
    app.main_h = main_h;

    // ---- header ----
    hline(buf, area.x, area.y, w);
    if header_h >= 3 {
        hline(buf, area.x, area.y + header_h - 1, w);
    }
    let title_y = area.y + 1;
    let mut x = 0u16;
    for s in left_title(app.view) {
        for (i, ch) in s.content.chars().enumerate() {
            put(buf, area.x + x + i as u16, title_y, &ch.to_string(), s.style);
        }
        x += s.content.chars().count() as u16;
    }
    let right = "flamelens v0.3.1";
    let rw = right.chars().count() as u16;
    if w > rw {
        for (i, ch) in right.chars().enumerate() {
            put(
                buf,
                area.x + w - rw + i as u16,
                title_y,
                &ch.to_string(),
                Style::new().bold(),
            );
        }
    }
    let ct = app.center_title();
    let rect_w = w.saturating_sub(36);
    let rect_h = if header_h >= 3 { header_h - 2 } else { 1 };
    if rect_w > 0 && rect_h > 0 {
        let chars: Vec<char> = ct.chars().collect();
        let n = chars.len();
        let mut consumed = 0usize;
        let mut row = 0u16;
        while consumed < n && row < rect_h {
            let chunk = (n - consumed).min(rect_w as usize);
            let s: String = chars[consumed..consumed + chunk].iter().collect();
            let off = ((rect_w as usize).saturating_sub(chunk) + 1) / 2;
            let sx = 20u16.saturating_add(off as u16);
            for (i, ch) in s.chars().enumerate() {
                put(
                    buf,
                    area.x + sx + i as u16,
                    title_y + row,
                    &ch.to_string(),
                    Style::new().bold(),
                );
            }
            consumed += chunk;
            row += 1;
        }
    }

    // ---- main ----
    let main_y = area.y + header_h;
    match app.view {
        View::Flamegraph => render_flamegraph(f, app, Rect::new(area.x, main_y, w, main_h)),
        View::Table => render_table(f, app, Rect::new(area.x, main_y, w, main_h)),
    }

    // ---- bottom panels ----
    let mut y = main_y + main_h;
    for (title, content) in panels {
        let tlen = title.chars().count() as u16;
        for (i, ch) in title.chars().enumerate() {
            put(buf, area.x + i as u16, y, &ch.to_string(), Style::new().bold().fg(ACCENT));
        }
        for xx in tlen..w {
            buf[(area.x + xx, y)].set_symbol(HLINE);
        }
        for (i, ch) in content.chars().enumerate() {
            put(buf, area.x + i as u16, y + 1, &ch.to_string(), Style::new());
        }
        y += 2;
    }

    // ---- separator + footer ----
    hline(buf, area.x, y, w);
    let footer = app.footer();
    let fl: usize = footer.iter().map(|s| s.content.chars().count()).sum();
    let fx = if (fl as u16) < w { (w - fl as u16) / 2 } else { 0 };
    let mut cx = fx;
    let fy = area.y + area.height - 1;
    for s in footer {
        for ch in s.content.chars() {
            put(buf, area.x + cx, fy, &ch.to_string(), s.style);
            cx += 1;
        }
    }
}

fn render_flamegraph(f: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 || area.width == 0 {
        return;
    }
    let t0 = Instant::now();
    let tree = &app.tree;
    let zoom = app.zoom;
    let total = app.zoom_total();
    let maxd = tree.levels.len().saturating_sub(1);
    let buf = f.buffer_mut();
    let start = app.scroll as usize;
    for row in 0..area.height as usize {
        let d = start + row;
        if d > maxd {
            break;
        }
        let mut x: u16 = 0;
        for &ix in &tree.levels[d] {
            if !tree.visible(zoom, ix) {
                continue;
            }
            let node = &tree.nodes[ix];
            let bw = if node.depth == 0 || Some(ix) == zoom {
                area.width
            } else {
                (node.count as f64 / total as f64 * area.width as f64) as u16
            };
            if bw == 0 {
                continue;
            }
            let dimmed = zoom.is_some() && node.depth != 0 && Some(ix) != zoom;
            let mut bg = node.color;
            if dimmed {
                bg = dim(bg);
            }
            let selected = ix == app.cursor;
            let matched = app
                .pattern
                .as_ref()
                .map(|r| r.is_match(&node.name))
                .unwrap_or(false);
            if selected {
                bg = BG_SELECTED;
            } else if matched {
                bg = BG_MATCH;
            }
            let fg = contrast(bg);
            let mut ranges: Vec<(usize, usize)> = Vec::new();
            if matched {
                if let Some(r) = app.pattern.as_ref() {
                    for m in r.find_iter(&node.name) {
                        ranges.push((m.start(), m.end()));
                    }
                }
            }
            if bw == 1 {
                put(
                    buf,
                    area.x + x,
                    area.y + row as u16,
                    ".",
                    Style::new().fg(fg).bg(bg),
                );
            } else {
                let label: Vec<char> = format!(" {}", node.name).chars().collect();
                for i in 0..bw as usize {
                    let ch = if i < label.len() { label[i] } else { ' ' };
                    let name_idx = i as i64 - 1;
                    let is_m = name_idx >= 0
                        && ranges
                            .iter()
                            .any(|&(a, b)| (name_idx as usize) >= a && (name_idx as usize) < b);
                    put(
                        buf,
                        area.x + x + i as u16,
                        area.y + row as u16,
                        &ch.to_string(),
                        Style::new()
                            .fg(if is_m { FG_MATCH } else { fg })
                            .bg(bg),
                    );
                }
            }
            x += bw;
        }
    }
    let el = t0.elapsed().as_secs_f64() * 1000.0;
    app.timings.insert("flamegraph".to_string(), el);
}

fn render_table(f: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 || area.width == 0 {
        return;
    }
    let buf = f.buffer_mut();
    let rows = app.table_rows();
    let n = rows.len();
    let hdr = if app.sort_by_total {
        format!("{:<15}{:<15}{}", format!("Total [{}]", DOWN), "Own", "Name")
    } else {
        format!("{:<15}{:<15}{}", "Total", format!("Own [{}]", DOWN), "Name")
    };
    let hstyle = Style::new().bold().reversed();
    for (i, ch) in hdr.chars().enumerate() {
        put(buf, area.x + i as u16, area.y, &ch.to_string(), hstyle);
    }
    for xx in hdr.chars().count() as u16..area.width {
        put(buf, area.x + xx, area.y, " ", hstyle);
    }
    let h = (area.height - 1) as usize;
    if app.table_cursor < app.table_scroll {
        app.table_scroll = app.table_cursor;
    } else if app.table_cursor >= app.table_scroll + h {
        app.table_scroll = app.table_cursor + 1 - h;
    }
    let base = app.tree.nodes[0].count as f64;
    for r in 0..(area.height as usize - 1) {
        let idx = app.table_scroll + r;
        if idx >= n {
            break;
        }
        let row = &rows[idx];
        let t = format!(
            "{:<15}{:<15}{}",
            format!("{} ({})", row.total, pct_str(row.total as f64, base)),
            format!("{} ({})", row.own, pct_str(row.own as f64, base)),
            row.name
        );
        let sel = idx == app.table_cursor;
        for (i, ch) in t.chars().enumerate() {
            if (i as u16) >= area.width {
                break;
            }
            let mut st = Style::new();
            if sel {
                st = st.bg(BG_TABLE_SEL);
            }
            put(buf, area.x + i as u16, area.y + 1 + r as u16, &ch.to_string(), st);
        }
        if sel {
            for xx in t.chars().count() as u16..area.width {
                put(buf, area.x + xx, area.y + 1 + r as u16, " ", Style::new().bg(BG_TABLE_SEL));
            }
        }
    }
}

// ---------------------------------------------------------------------------
// key handling
// ---------------------------------------------------------------------------

fn handle_key(app: &mut App, key: KeyEvent) {
    if let Some(inp) = app.input.as_mut() {
        match key.code {
            KeyCode::Esc => {
                app.input = None;
            }
            KeyCode::Enter => {
                let src = inp.clone();
                app.input = None;
                match regex::Regex::new(&src) {
                    Ok(r) => {
                        app.pattern = Some(r);
                        app.pattern_src = Some(src);
                        app.info = None;
                    }
                    Err(_) => {
                        app.pattern = None;
                        app.pattern_src = None;
                        app.info = Some(format!("Invalid regex: {}", src));
                    }
                }
            }
            KeyCode::Backspace => {
                inp.pop();
            }
            KeyCode::Char(c) => inp.push(c),
            _ => {}
        }
        return;
    }
    match key.code {
        KeyCode::Char('q') => app.quit = true,
        KeyCode::Char('c')
            if key.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) =>
        {
            app.quit = true
        }
        KeyCode::Esc => {
            if app.zoom.is_some() {
                app.zoom = None;
            }
        }
        KeyCode::Tab => {
            app.view = if app.view == View::Flamegraph {
                View::Table
            } else {
                View::Flamegraph
            };
        }
        KeyCode::Char('r') => {
            app.zoom = None;
            app.scroll = 0;
            app.table_scroll = 0;
            app.table_cursor = 0;
            app.pattern = None;
            app.pattern_src = None;
            app.info = None;
            app.cursor = 0;
            app.view = View::Flamegraph;
        }
        KeyCode::Enter => {
            if app.view == View::Flamegraph {
                app.zoom = Some(app.cursor);
            }
        }
        KeyCode::Char('f') => {
            if app.view == View::Flamegraph {
                let h = app.main_h as usize;
                let maxl = app.tree.levels.len().saturating_sub(1);
                let max = maxl.saturating_sub(h);
                app.scroll = (app.scroll as usize + h).min(max) as u16;
                snap_cursor(app);
            } else {
                let n = app.table_rows().len();
                let h = app.main_h as usize;
                app.table_scroll =
                    (app.table_scroll as usize + h).min(n.saturating_sub(1)) as u16;
                if app.table_cursor < app.table_scroll
                    || app.table_cursor >= app.table_scroll + h.saturating_sub(1)
                {
                    app.table_cursor = app.table_scroll;
                }
            }
        }
        KeyCode::Char('b') => {
            if app.view == View::Flamegraph {
                app.scroll = app.scroll.saturating_sub(app.main_h);
                snap_cursor(app);
            } else {
                app.table_scroll = app.table_scroll.saturating_sub(app.main_h);
                let h = app.main_h as usize;
                if app.table_cursor < app.table_scroll
                    || app.table_cursor >= app.table_scroll + h.saturating_sub(1)
                {
                    app.table_cursor = app.table_scroll;
                }
            }
        }
        KeyCode::Char('g') => {
            if app.view == View::Flamegraph {
                app.scroll = 0;
                snap_cursor(app);
            }
        }
        KeyCode::Char('G') => {
            if app.view == View::Flamegraph {
                let h = app.main_h as usize;
                let maxl = app.tree.levels.len().saturating_sub(1);
                app.scroll = maxl.saturating_sub(h) as u16;
                snap_cursor(app);
            }
        }
        KeyCode::Char('/') => app.input = Some(String::new()),
        KeyCode::Char('#') => {
            let name = app.tree.nodes[app.cursor].name.clone();
            let src = format!("^{}$", name);
            match regex::Regex::new(&src) {
                Ok(r) => {
                    app.pattern = Some(r);
                    app.pattern_src = Some(src);
                    app.info = None;
                }
                Err(_) => {
                    app.pattern = None;
                    app.pattern_src = None;
                    app.info = Some(format!("Invalid regex: {}", src));
                }
            }
        }
        KeyCode::Char('n') => jump_match(app, 1),
        KeyCode::Char('N') => jump_match(app, -1),
        KeyCode::Char('1') => {
            if app.view == View::Table {
                app.sort_by_total = true;
            }
        }
        KeyCode::Char('2') => {
            if app.view == View::Table {
                app.sort_by_total = false;
            }
        }
        KeyCode::Char('j') | KeyCode::Down => {
            if app.view == View::Flamegraph {
                move_down(app);
            } else {
                let n = app.table_rows().len();
                if app.table_cursor + 1 < n {
                    app.table_cursor += 1;
                }
            }
        }
        KeyCode::Char('k') | KeyCode::Up => {
            if app.view == View::Flamegraph {
                move_up(app);
            } else {
                app.table_cursor = app.table_cursor.saturating_sub(1);
            }
        }
        KeyCode::Char('h') | KeyCode::Left => {
            if app.view == View::Flamegraph {
                move_side(app, -1);
            }
        }
        KeyCode::Char('l') | KeyCode::Right => {
            if app.view == View::Flamegraph {
                move_side(app, 1);
            }
        }
        _ => {}
    }
    if app.view == View::Flamegraph {
        follow_cursor(app);
    } else {
        let h = (app.main_h as usize).saturating_sub(1);
        if h == 0 {
            return;
        }
        if app.table_cursor < app.table_scroll {
            app.table_scroll = app.table_cursor;
        } else if app.table_cursor >= app.table_scroll + h {
            app.table_scroll = app.table_cursor + 1 - h;
        }
    }
}

fn snap_cursor(app: &mut App) {
    let h = app.main_h as usize;
    if h == 0 {
        return;
    }
    let cd = app.tree.nodes[app.cursor].depth;
    if cd < app.scroll as usize || cd >= app.scroll as usize + h {
        let target = app.scroll as usize;
        for &ix in app.tree.levels.get(target).unwrap_or(&Vec::new()) {
            if app.tree.visible(app.zoom, ix) {
                app.cursor = ix;
                return;
            }
        }
    }
}

fn follow_cursor(app: &mut App) {
    let h = app.main_h as usize;
    if h == 0 {
        return;
    }
    let cd = app.tree.nodes[app.cursor].depth;
    if cd < app.scroll as usize {
        app.scroll = cd as u16;
    } else if cd >= app.scroll as usize + h {
        app.scroll = (cd - h + 1) as u16;
    }
}

fn move_down(app: &mut App) {
    let node = &app.tree.nodes[app.cursor];
    if node.children.is_empty() {
        return;
    }
    let best = *node
        .children
        .iter()
        .max_by_key(|&c| app.tree.nodes[*c].count)
        .unwrap();
    app.cursor = best;
}

fn move_up(app: &mut App) {
    let node = &app.tree.nodes[app.cursor];
    if node.depth == 0 {
        return;
    }
    app.cursor = node.parent;
}

fn move_side(app: &mut App, dir: i32) {
    let parent = app.tree.nodes[app.cursor].parent;
    let kids = app.tree.nodes[parent].children.clone();
    let pos = match kids.iter().position(|&k| k == app.cursor) {
        Some(p) => p,
        None => return,
    };
    let total = app.zoom_total();
    let w = app.widths(total, app.main_w);
    let mut p = pos as i64;
    loop {
        p += dir as i64;
        if p < 0 || p >= kids.len() as i64 {
            return;
        }
        if w[kids[p as usize]] > 0 {
            app.cursor = kids[p as usize];
            return;
        }
    }
}

fn jump_match(app: &mut App, dir: i32) {
    let rx = match app.pattern.clone() {
        Some(r) => r,
        None => return,
    };
    let total = app.zoom_total();
    let w = app.widths(total, app.main_w);
    let mut list: Vec<usize> = Vec::new();
    for l in &app.tree.levels {
        for &i in l {
            if w[i] > 0 && rx.is_match(&app.tree.nodes[i].name) {
                list.push(i);
            }
        }
    }
    if list.is_empty() {
        return;
    }
    match list.iter().position(|&i| i == app.cursor) {
        Some(p) => {
            let np = p as i64 + dir as i64;
            if np >= 0 && (np as usize) < list.len() {
                app.cursor = list[np as usize];
            }
        }
        None => {
            if dir > 0 {
                app.cursor = list[0];
            }
        }
    }
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

fn main() {
    let args = parse_args();
    let data = match &args.filename {
        Some(f) => std::fs::read_to_string(f).expect("Could not read file"),
        None => {
            let mut s = String::new();
            io::stdin().read_to_string(&mut s).unwrap_or_default();
            s
        }
    };
    let tree = Tree::build(&data, args.sorted);
    let res = run_app(tree, args, &data);
    if res.is_err() {
        std::process::exit(1);
    }
}

fn run_app(tree: Tree, args: Args, data: &str) -> io::Result<()> {
    crossterm::terminal::enable_raw_mode()?;
    let mut stderr = io::stderr();
    execute!(
        stderr,
        crossterm::terminal::EnterAlternateScreen,
        crossterm::cursor::Hide
    )?;
    let backend = CrosstermBackend::new(stderr);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;
    let mut app = App::new(tree, args);
    app.main_w = terminal.size()?.width;
    let mut last_tick = Instant::now();
    loop {
        let t0 = Instant::now();
        let flame_t = {
            let mut t = Duration::ZERO;
            terminal.draw(|f| {
                let s = Instant::now();
                render(f, &mut app);
                t = s.elapsed();
            });
            t
        };
        app.timings
            .insert("flamegraph".to_string(), flame_t.as_secs_f64() * 1000.0);
        app.timings
            .insert("render".to_string(), t0.elapsed().as_secs_f64() * 1000.0);
        let timeout = Duration::from_millis(100).saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    let k0 = Instant::now();
                    handle_key(&mut app, key);
                    app.timings
                        .insert("handle_key_events".to_string(), k0.elapsed().as_secs_f64() * 1000.0);
                }
            }
        }
        if last_tick.elapsed() >= Duration::from_millis(100) {
            last_tick = Instant::now();
        }
        if app.quit {
            break;
        }
    }
    crossterm::terminal::disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        crossterm::terminal::LeaveAlternateScreen,
        event::DisableMouseCapture
    )?;
    terminal.show_cursor()?;
    if args.echo {
        println!("{}", data);
    }
    Ok(())
}
